  (forall st' (p : optr) s' ms' (r : option bptr),
     Q1 (st', p) s' ms' -> ptr_rel p r ->
     (forall b, r = Some b -> snd b = fresh_off (strip st') (fst b) n) ->
     Q r (set_m (strip st') s') ms') ->
  implM rsegs (raw_malloc n) s Q ms.
Proof.
